const results = [];

for (const item of $input.all()) {
  const binary = item.binary || {};
  const json = item.json;

  const messageId = json.messageId || String(json.uid || json.id || '');
  const fromRaw = json.from;
  let emailExpediteur = 'inconnu@email.com';
  if (typeof fromRaw === 'string') {
    emailExpediteur = fromRaw;
  } else if (fromRaw?.value?.[0]?.address) {
    emailExpediteur = fromRaw.value[0].address;
  } else if (fromRaw?.text) {
    emailExpediteur = fromRaw.text;
  }

  const sujet = json.subject || '(sans objet)';
  const dateReception = json.date || new Date().toISOString();

  for (const [key, attachment] of Object.entries(binary)) {
    const mimeType = (attachment.mimeType || attachment.fileType || '').toLowerCase();
    let isPdf = mimeType === 'application/pdf' || mimeType.includes('pdf');

    if (!isPdf && attachment.data) {
      try {
        const header = Buffer.from(attachment.data, 'base64').slice(0, 4).toString('ascii');
        isPdf = header === '%PDF';
      } catch (_) {
        isPdf = false;
      }
    }

    if (isPdf) {
      results.push({
        json: {
          messageId,
          email_expediteur: emailExpediteur,
          sujet_email: sujet,
          date_reception: dateReception,
          nom_fichier_cv: attachment.fileName || attachment.filename || 'document.pdf',
          attachment_key: key
        },
        binary: {
          pdf: attachment
        }
      });
    }
  }
}

return results;

const items = $input.all();
let extracted = null;
let offre = null;

for (const item of items) {
  const j = item.json;
  if (j.text) {
    extracted = j;
  } else if (j.titre && j.description) {
    offre = j;
  }
}

const meta = $('Filtrer pièces jointes PDF').item.json;

if (!extracted?.text) throw new Error('Texte CV manquant après extraction PDF');
if (!offre) throw new Error('Aucune offre d\'emploi active en base');

const competencesReq = typeof offre.competences_requises === 'string'
  ? offre.competences_requises
  : JSON.stringify(offre.competences_requises || []);

const prompt = `Tu es un assistant RH expert. Analyse le CV suivant par rapport à l'offre d'emploi.

OFFRE D'EMPLOI : ${offre.titre}
${offre.description}
Compétences requises : ${competencesReq}

CV DU CANDIDAT :
${extracted.text.substring(0, 12000)}

Réponds UNIQUEMENT avec un objet JSON valide, sans markdown ni texte autour :
{
  "resume": "résumé du profil en 3 à 5 phrases",
  "competences": ["compétence1", "compétence2"],
  "score_compatibilite": 75,
  "points_forts": ["point fort 1"],
  "points_faibles": ["point faible 1"]
}

Le score_compatibilite doit être un entier entre 0 et 100.`;

return [{
  json: {
    prompt,
    messageId: meta.messageId,
    email_expediteur: meta.email_expediteur,
    sujet_email: meta.sujet_email,
    date_reception: meta.date_reception,
    nom_fichier_cv: meta.nom_fichier_cv,
    texte_cv: extracted.text,
    offre_emploi_id: offre.id,
    offre_titre: offre.titre
  }
}];

const ollamaResponse = $input.first().json;
const prev = $('Préparer prompt IA').first().json;

let raw = ollamaResponse.response || '';
raw = raw.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();

let analysis;
try {
  analysis = JSON.parse(raw);
} catch (e) {
  throw new Error('Réponse Ollama non parsable en JSON : ' + raw.substring(0, 500));
}

const score = Math.min(100, Math.max(0, parseInt(analysis.score_compatibilite, 10) || 0));

return [{
  json: {
    message_id: prev.messageId,
    email_expediteur: prev.email_expediteur,
    sujet_email: prev.sujet_email,
    date_reception: prev.date_reception,
    nom_fichier_cv: prev.nom_fichier_cv,
    texte_cv: prev.texte_cv,
    resume_candidat: analysis.resume || '',
    competences: analysis.competences || [],
    score_compatibilite: score,
    points_forts: analysis.points_forts || [],
    points_faibles: analysis.points_faibles || [],
    analyse_complete: analysis,
    offre_emploi_id: prev.offre_emploi_id,
    offre_titre: prev.offre_titre
  }
}];

const parsed = $('Parser réponse IA').first().json;

if (!parsed?.email_expediteur) {
  throw new Error('Données candidature manquantes pour la notification');
}

const score = parsed.score_compatibilite;
const emoji = score >= 80 ? '🟢' : score >= 60 ? '🟡' : '🔴';

const competences = (parsed.competences || []).map(c => `  • ${c}`).join('\n');
const pointsForts = (parsed.points_forts || []).map(p => `  • ${p}`).join('\n');

const html = `
<h2>${emoji} Nouvelle candidature analysée</h2>
<p><strong>Candidat :</strong> ${parsed.email_expediteur}</p>
<p><strong>Offre :</strong> ${parsed.offre_titre}</p>
<p><strong>Score de compatibilité :</strong> ${score}/100</p>
<h3>Résumé</h3>
<p>${parsed.resume_candidat}</p>
<h3>Compétences détectées</h3>
<pre>${competences}</pre>
<h3>Points forts</h3>
<pre>${pointsForts}</pre>
<p><em>CV : ${parsed.nom_fichier_cv} - Traitement automatique Assistant RH IA</em></p>
`;

return [{
  json: {
    to: '@@RECRUITER_EMAIL@@',
    subject: `[RH IA] Candidature ${parsed.email_expediteur} - Score ${score}/100`,
    html
  }
}];
